package com.company.iaf.qms.engineering.infrastructure.persistence;
import com.company.iaf.qms.engineering.application.QmsEngineeringErrorCode;
import com.company.iaf.platform.core.security.RequiresPermission;import com.company.iaf.qms.engineering.domain.repository.*;import com.company.iaf.qms.engineering.interfaces.dto.*;import com.company.iaf.shared.exception.BusinessException;import com.company.iaf.shared.security.SecurityContext;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class InspectionStandardService{
 private final JdbcTemplate jdbc;private final DrawingRevisionRepository revisions;private final QmsAuditTrail audit;public InspectionStandardService(JdbcTemplate j,DrawingRevisionRepository r,QmsAuditTrail a){jdbc=j;revisions=r;audit=a;}
 @RequiresPermission("qms:drawing-revision:view") @Transactional(readOnly=true) public InspectionStandardResponse get(long t,long o,long r){requireRevision(t,o,r);return find(t,o,r).orElse(null);}
 @RequiresPermission("qms:inspection-standard:edit") @Transactional public InspectionStandardResponse generate(long t,long o,long r){requireRevision(t,o,r);var old=find(t,o,r);if(old.isPresent())return old.get();var src=jdbc.queryForList("select q.*,d.drawing_no from qms_quality_characteristic q join qms_drawing_revision v on v.tenant_id=q.tenant_id and v.id=q.drawing_revision_id join qms_drawing d on d.tenant_id=v.tenant_id and d.id=v.drawing_id where q.tenant_id=? and q.org_id=? and q.drawing_revision_id=? and q.review_status='CONFIRMED' and q.deleted=false and (q.inspection_dimension or q.mandatory_inspection) and not q.reference_dimension and not q.ideal_dimension order by q.id",t,o,r);if(src.isEmpty())throw new BusinessException(QmsEngineeringErrorCode.INSPECTION_STANDARD_NO_ELIGIBLE_SOURCE);long actor=SecurityContext.getUserId().orElse(0L);var first=src.getFirst();Long id=jdbc.queryForObject("insert into qms_inspection_standard(tenant_id,org_id,standard_no,part_id,drawing_revision_id,created_by,updated_by) values(?,?,?,?,?,?,?) returning id",Long.class,t,o,"IS-"+first.get("drawing_no")+"-1",first.get("part_id"),r,actor,actor);int seq=1;for(var x:src)jdbc.update("insert into qms_inspection_standard_item(tenant_id,org_id,inspection_standard_id,sequence_no,category,item_name,requirement,characteristic_id,nominal_value,lower_limit,upper_limit,special_characteristic_code,supplier_batch_sampling,supplier_batch_method,supplier_annual_sampling,supplier_annual_method,evidence_id,confidence,created_by,updated_by) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",t,o,id,seq++,category(String.valueOf(x.get("characteristic_type"))),x.get("name"),requirement(x),x.get("id"),x.get("nominal_value"),x.get("lower_limit"),x.get("upper_limit"),x.get("special_characteristic_code"),"每批","按图纸检验","每年一次","全尺寸检验",x.get("evidence_id"),x.get("confidence"),actor,actor);var result=find(t,o,r).orElseThrow();audit.record(t,actor,"INSPECTION_STANDARD_DRAFT_GENERATED","InspectionStandard",id,result);return result;}
 @RequiresPermission("qms:inspection-standard:edit") @Transactional public InspectionStandardResponse update(long t,long o,long r,long id,InspectionStandardUpdateRequest q){var current=find(t,o,r).filter(v->v.id()==id).orElseThrow(()->new BusinessException(QmsEngineeringErrorCode.INSPECTION_STANDARD_NOT_FOUND));long actor=SecurityContext.getUserId().orElse(0L);if(jdbc.update("update qms_inspection_standard set reaction_plan=?,status='DRAFT',updated_by=?,updated_at=current_timestamp,version=version+1 where tenant_id=? and org_id=? and id=? and version=? and deleted=false",q.reactionPlan(),actor,t,o,id,q.version())!=1)throw new BusinessException(QmsEngineeringErrorCode.INSPECTION_STANDARD_CONFLICT);for(var i:q.items())if(jdbc.update("update qms_inspection_standard_item set requirement=?,supplier_batch_sampling=?,supplier_batch_method=?,supplier_annual_sampling=?,supplier_annual_method=?,remark=?,review_status='CONFIRMED',updated_by=?,updated_at=current_timestamp,version=version+1 where tenant_id=? and org_id=? and inspection_standard_id=? and id=? and deleted=false",i.requirement(),i.supplierBatchSampling(),i.supplierBatchMethod(),i.supplierAnnualSampling(),i.supplierAnnualMethod(),i.remark(),actor,t,o,id,i.id())!=1)throw new BusinessException(QmsEngineeringErrorCode.INSPECTION_STANDARD_CONFLICT);var result=find(t,o,r).orElseThrow();audit.record(t,actor,"INSPECTION_STANDARD_DRAFT_UPDATED","InspectionStandard",id,result);return result;}
 private Optional<InspectionStandardResponse> find(long t,long o,long r){var ss=jdbc.queryForList("select * from qms_inspection_standard where tenant_id=? and org_id=? and drawing_revision_id=? and deleted=false order by document_version desc limit 1",t,o,r);if(ss.isEmpty())return Optional.empty();var s=ss.getFirst();long id=(long)s.get("id");var items=jdbc.query("select * from qms_inspection_standard_item where tenant_id=? and org_id=? and inspection_standard_id=? and deleted=false order by sequence_no",(x,n)->new InspectionStandardResponse.Item(x.getLong("id"),x.getInt("sequence_no"),x.getString("category"),x.getString("item_name"),x.getString("requirement"),x.getLong("characteristic_id"),x.getBigDecimal("nominal_value"),x.getBigDecimal("lower_limit"),x.getBigDecimal("upper_limit"),x.getString("special_characteristic_code"),x.getString("supplier_batch_sampling"),x.getString("supplier_batch_method"),x.getString("supplier_annual_sampling"),x.getString("supplier_annual_method"),x.getString("remark"),x.getString("source_type"),(Long)x.getObject("evidence_id"),x.getBigDecimal("confidence"),x.getString("review_status")),t,o,id);return Optional.of(new InspectionStandardResponse(id,(String)s.get("standard_no"),(long)s.get("part_id"),r,(int)s.get("document_version"),(String)s.get("status"),(String)s.get("source_type"),(String)s.get("reaction_plan"),(int)s.get("version"),((java.sql.Timestamp)s.get("updated_at")).toLocalDateTime(),items));}
 private void requireRevision(long t,long o,long r){if(revisions.findById(t,o,r).isEmpty())throw new BusinessException(QmsEngineeringErrorCode.REVISION_NOT_FOUND);}private static String category(String v){return switch(v){case"DIMENSION"->"DIMENSION";case"APPEARANCE"->"APPEARANCE";case"PERFORMANCE"->"PERFORMANCE";default->"OTHER";};}private static String requirement(Map<String,Object>x){return x.get("nominal_value")+(x.get("lower_limit")==null?"":" ("+x.get("lower_limit")+" ~ "+x.get("upper_limit")+")");}
}
